- bash (intenção: Compiling verification harness for new APIs | comando: mkdir -p /tmp/r100/src && cd /tmp/r100 && cat > Cargo.toml <<'EOF'
[package]
name = "r100"
version = "0.1.0"
edition = "2024"
EOF
cat > src/main.rs <<'EOF'
use std::alloc::{Allocator, Global, Layout, System, AllocError};
use std::borrow::Cow;
use std::cell::UnsafeCell;
use std::convert::Infallible;
use std::mem::DropGuard;
use std::path::Path;
use std::ptr::NonNull;
use std::rc::Rc;
use std::sync::Arc;

// --- custom allocator: counting wrapper over System ---
#[derive(Clone, Copy, Default)]
struct Counting;

unsafe impl Allocator for Counting {
    fn allocate(&self, layout: Layout) -> Result<NonNull<[u8]>, AllocError> {
        System.allocate(layout)
    }
    unsafe fn deallocate(&self, ptr: NonNull<u8>, layout: Layout) {
        unsafe { System.deallocate(ptr, layout) }
    }
}

fn never_result() -> Result<u32, !> { Ok(1) }
fn takes_infallible(r: Result<u8, Infallible>) -> u8 { match r { Ok(v) => v } }

fn parse_all(nums: &mut Vec<u32>, strings: &[&str]) -> Result<(), std::num::ParseIntError> {
    let len = nums.len();
    let mut nums = DropGuard::new(nums, move |nums| nums.truncate(len));
    for s in strings { nums.push(s.parse()?); }
    DropGuard::dismiss(nums);
    Ok(())
}

fn main() {
    // never type
    let Ok(v) = never_result();
    assert_eq!(v, 1);
    let _ = takes_infallible(Ok(3u8));
    let _: Result<u32, !> = Ok(7);
    // Infallible is ! now
    let _: ! = return;
    // AsRef/AsMut for !
    fn need_as_ref<T: AsRef<str>>(x: T) -> bool { x.as_ref().len() == 0 }
    let _ = need_as_ref::<!>;

    // allocator API
    let b: Box<i32, Counting> = Box::new_in(5, Counting);
    assert_eq!(*b, 5);
    let b = Box::new_in(5, System);
    let (ptr, alloc) = Box::into_raw_with_allocator(b);
    let b = unsafe { Box::from_raw_in(ptr, alloc) };
    assert_eq!(*b, 5);
    let b2 = Box::new_in(6, System);
    let (nn, alloc2) = Box::into_non_null_with_allocator(b2);
    let b2 = unsafe { Box::from_non_null_in(nn, alloc2) };
    assert_eq!(*b2, 6);
    assert_eq!(Box::allocator(&*b), &System);

    let mut vec: Vec<i32, Counting> = Vec::new_in(Counting);
    vec.push(1);
    let mut v2: Vec<i32, System> = Vec::with_capacity_in(4, System);
    v2.extend([1, 2, 3]);
    let (p, len, cap, a) = v2.into_parts_with_allocator();
    let v2 = unsafe { Vec::from_parts_in(p, len, cap, a) };
    assert_eq!(v2, [1, 2, 3]);
    assert_eq!(v2.allocator(), &System);
    let (p, len, cap, a) = v2.into_raw_parts_with_allocator();
    let v2 = unsafe { Vec::from_raw_parts_in(p, len, cap, a) };
    assert_eq!(v2.len(), 3);

    // Global as allocator value
    let g: Vec<u8, Global> = Vec::new_in(Global);
    assert!(g.is_empty());

    // Box::take / map
    let c = Box::new(5);
    let (value, uninit) = Box::take(c);
    assert_eq!(value, 5);
    let c = Box::write(uninit, 6);
    assert_eq!(*c, 6);
    let new = Box::map(c, |i| i + 7);
    assert_eq!(*new, 13);

    // Rc::map / Arc::map
    let r = Rc::new(7);
    let r2 = Rc::map(r, |x| x + 1);
    assert_eq!(*r2, 8);
    let a = Arc::new(7);
    let a2 = Arc::map(a, |x| x * 2);
    assert_eq!(*a2, 14);

    // DropGuard rollback
    let mut nums = vec![1];
    assert!(parse_all(&mut nums, &["2", "x"]).is_err());
    assert_eq!(nums, [1]);
    assert!(parse_all(&mut nums, &["2", "3"]).is_ok());
    assert_eq!(nums, [1, 2, 3]);

    // conjure_zst
    assert_eq!(unsafe { std::mem::conjure_zst::<()>() }, ());
    assert_eq!(unsafe { std::mem::conjure_zst::<[i32; 0]>() }, []);

    // bool::toggle
    let mut flag = false;
    flag.toggle();
    assert!(flag);

    // trim_prefix / trim_suffix
    assert_eq!("foo:bar".trim_prefix("foo:"), "bar");
    assert_eq!("foo.txt".trim_suffix(".txt"), "foo");
    let v = &[10, 40, 30];
    assert_eq!(v.trim_prefix(&[10]), &[40, 30]);
    assert_eq!(v.trim_suffix(&[30]), &[10, 40]);
    assert_eq!(Path::new("/test/haha/foo.txt").trim_prefix("/test"), Path::new("haha/foo.txt"));
    assert_eq!(Path::new("src/lib.rs").trim_suffix(".rs"), Path::new("src/lib"));

    // Vec::from_fn
    let sq = Vec::from_fn(5, |i| i * i);
    assert_eq!(sq, [0, 1, 4, 9, 16]);

    // UnsafeCell unchecked accessors + replace
    let uc = UnsafeCell::new(5);
    let old = unsafe { uc.replace(10) };
    assert_eq!(old, 5);
    assert_eq!(unsafe { *uc.as_ref_unchecked() }, 10);
    unsafe { *uc.as_mut_unchecked() += 1; }
    assert_eq!(uc.into_inner(), 11);

    // Once::default
    let once = std::sync::Once::default();
    once.call_once(|| {});

    // Vec == Cow<[T]>
    let v = vec![1, 2, 3];
    let c: Cow<'_, [i32]> = Cow::Borrowed(&[1, 2, 3]);
    assert_eq!(v, c);
    let s: &[i32] = &[1, 2, 3];
    assert_eq!(s, c);

    println!("all ok");
}
EOF
cargo run -q 2>&1 | tail -40)

